void RemainingDistanceTimeCalculatorNode::on_timer()
{
  autoware_utils_debug::ScopedTimeTrack st(__func__, *time_keeper_);
  if (!has_received_scenario_) {
    return;
  }

  // check if the scenario is parking or not
  if (scenario_->current_scenario == autoware_internal_planning_msgs::msg::Scenario::PARKING) {
    remaining_distance_ = 0.0;
    remaining_time_ = 0.0;
    publish_mission_remaining_distance_time();
  } else if (is_graph_ready_ && has_received_route_) {
    calculate_remaining_distance();
    calculate_remaining_time();
    publish_mission_remaining_distance_time();
  }
}

void RemainingDistanceTimeCalculatorNode::calculate_remaining_distance()
{
  const auto current_lanelet_opt =
    experimental::lanelet2_utils::get_closest_lanelet(current_lanes_, current_vehicle_pose_);
  if (!current_lanelet_opt) {
    RCLCPP_WARN_STREAM_THROTTLE(
      this->get_logger(), *get_clock(), 3000, "Failed to find current lanelet.");

    return;
  }
  const auto & current_lanelet = current_lanelet_opt.value();

  if (
    current_lanes_.empty() || current_lanes_lengths_.empty() ||
    current_lanes_.size() != current_lanes_lengths_.size()) {
    RCLCPP_WARN_STREAM_THROTTLE(
      this->get_logger(), *get_clock(), 3000, "Current lanes are empty or misconfigured.");
    return;
  }

  auto current_lane_itr = std::find_if(
    current_lanes_.begin(), current_lanes_.end(),
    [&current_lanelet](const lanelet::ConstLanelet & llt) {
      return llt.id() == current_lanelet.id();
    });

  if (current_lane_itr == current_lanes_.end()) {
    RCLCPP_WARN_STREAM_THROTTLE(
      this->get_logger(), *get_clock(), 3000, "Failed to find current lanelet in current lanes.");
    return;
  }

  remaining_distance_ = std::invoke([&]() -> double {
    // remaining distance in current lanelet (if it is not the goal lanelet)
    lanelet::ArcCoordinates arc_coord = autoware::experimental::lanelet2_utils::get_arc_coordinates(
      lanelet::ConstLanelets{current_lanelet}, current_vehicle_pose_);
    double this_lanelet_length = lanelet::geometry::length2d(current_lanelet);
    double dist_in_current_lanelet =
      (current_lanelet.id() != goal_lanelet_.id()) ? this_lanelet_length - arc_coord.length : 0.0;

    // distance from remaining lanelets between current lanelet and goal lanelet, if there are any
    const auto index = std::distance(current_lanes_.begin(), current_lane_itr);
    double middle_lanes_distance =
      (static_cast<std::size_t>(index + 1) < current_lanes_lengths_.size() - 1)
        ? std::accumulate(
            current_lanes_lengths_.begin() + index + 1, current_lanes_lengths_.end() - 1, 0.0)
        : 0.0;

    // remaining distance in goal lanelet
    double dist_in_goal_lanelet =
      (current_lanelet.id() != goal_lanelet_.id())
        ? autoware::experimental::lanelet2_utils::get_arc_coordinates({goal_lanelet_}, goal_pose_)
            .length
        : autoware::experimental::lanelet2_utils::get_arc_coordinates({goal_lanelet_}, goal_pose_)
              .length -
            arc_coord.length;
    return std::max(dist_in_current_lanelet + middle_lanes_distance + dist_in_goal_lanelet, 0.0);
  });
}

std::optional<lanelet::ConstLanelet> get_closest_lanelet(
  const lanelet::ConstLanelets & lanelets, const geometry_msgs::msg::Pose & search_pose)
{
  if (lanelets.empty()) {
    return std::nullopt;
  }

  const lanelet::BasicPoint3d search_point = from_ros(search_pose);

  lanelet::ConstLanelets candidate_lanelets;
  double min_distance = std::numeric_limits<double>::max();
  for (const auto & llt : lanelets) {
    /*
      NOTE(soblin):
      if point is on the edge of, or within the area of that polygon, distance is
      0.0.
      comparable_distance is a distance that maybe be x*x+y*y, not std::hypot of it,
      which is used to only compare distance
      stackoverflow.com/questions/51267577/boost-geometry-polygon-distance-for-inside-point
     */
    const double distance = boost::geometry::comparable_distance(
      llt.polygon2d().basicPolygon(), lanelet::utils::to2D(search_point));

    /*
      NOTE(soblin): this line is intended to push all lanelets on which search_point is located to
      candidate, and later judge by angle
     */
    if (std::fabs(distance - min_distance) <= std::numeric_limits<double>::epsilon()) {
      candidate_lanelets.push_back(llt);
    } else if (distance < min_distance) {
      candidate_lanelets.clear();
      candidate_lanelets.push_back(llt);
      min_distance = distance;
    }
  }

  if (candidate_lanelets.size() == 1) {
    return candidate_lanelets.front();
  }

  // find by angle
  const double pose_yaw = tf2::getYaw(search_pose.orientation);
  double min_angle = std::numeric_limits<double>::max();
  std::optional<lanelet::ConstLanelet> closest_lanelet{};
  for (const auto & llt : candidate_lanelets) {
    const lanelet::ConstLineString3d segment = get_closest_segment(llt.centerline(), search_point);
    if (segment.empty()) {
      continue;
    }
    const auto segment_angle = std::atan2(
      segment.back().y() - segment.front().y(), segment.back().x() - segment.front().x());
    const auto angle_diff =
      std::fabs(autoware_utils_math::normalize_radian(segment_angle - pose_yaw));
    if (angle_diff < min_angle) {
      min_angle = angle_diff;
      closest_lanelet = llt;
    }
  }
  return closest_lanelet;
}

lanelet::ConstLineString3d get_closest_segment(
  const lanelet::ConstLineString3d & linestring, const lanelet::BasicPoint3d & search_pt)
{
  lanelet::ConstLineString3d closest_segment;
  double min_distance = std::numeric_limits<double>::max();

  for (const auto & [prev_pt, current_pt] :
       ranges::views::zip(linestring, linestring | ranges::views::drop(1))) {
    lanelet::Point3d prev_pt_3d(lanelet::InvalId, prev_pt.x(), prev_pt.y(), prev_pt.z());
    lanelet::Point3d current_pt_3d(
      lanelet::InvalId, current_pt.x(), current_pt.y(), current_pt.z());

    lanelet::ConstLineString3d current_segment(lanelet::InvalId, {prev_pt_3d, current_pt_3d});
    double distance = lanelet::geometry::distance3d(current_segment.basicLineString(), search_pt);
    if (distance < min_distance) {
      closest_segment = current_segment;
      min_distance = distance;
    }
  }
  return closest_segment;
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

lanelet::ArcCoordinates get_arc_coordinates(
  const lanelet::ConstLanelets & lanelets, const geometry_msgs::msg::Pose & pose)
{
  // Handle empty Input (Return default ArcCoordinates)
  if (lanelets.empty()) {
    RCLCPP_WARN(
      rclcpp::get_logger("autoware_lanelet2_utility"),
      "Input lanelets is empty. Returning default ArcCoordinates (length=0, distance=0).");
    return lanelet::ArcCoordinates();
  }
  const auto lanelet_sequence = lanelet::LaneletSequence(lanelets);
  const auto centerline_2d = lanelet_sequence.centerline2d();

  const auto lanelet_point = from_ros(pose);

  lanelet::ArcCoordinates arc_coordinates = lanelet::geometry::toArcCoordinates(
    centerline_2d, lanelet::utils::to2D(lanelet_point).basicPoint());

  return arc_coordinates;
}

lanelet::ConstPoint3d from_ros(const geometry_msgs::msg::Pose & src)
{
  return from_ros(src.position);
}

lanelet::ConstPoint3d from_ros(const geometry_msgs::msg::Point & src)
{
  return lanelet::ConstPoint3d(lanelet::Point3d(lanelet::InvalId, src.x, src.y, src.z));
}
